import { createEffect, createMemo, createSignal, For, Show, type Component } from "solid-js";

import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { RingMeter } from "#core/ui-next/components/ring-meter.jsx";
import { TooltipKeyword } from "#core/ui-next/components/tooltip-keyword.jsx";
import { Tooltip, TooltipHorizontalPosition, TooltipVerticalPosition } from "#core/ui-next/components/tooltip.jsx";

import { EntryDivider, TicketSection } from "#base/ui-next/tooltips/plot-tooltip/components/utility.jsx";
import { ProductionTooltip } from "#base/ui-next/tooltips/production-tooltip.jsx";

import { type ProductionQueueItem } from "./city-banner-data.js";

export interface CityBannerProductionProps {
	currentProduction: ProductionQueueItem | undefined;
	buildQueue: ProductionQueueItem[];
	turnsLeft: number;
	percent: number;
}

export const CityBannerProduction: Component<CityBannerProductionProps> = (props) => {
	const [currentProd, setCurrentProd] = createSignal<ProductionQueueItem | undefined>(undefined);
	const [buildQueue, setBuildQueue] = createSignal<ProductionQueueItem[]>([]);

	// Commented out until Efficiencies are sorted out on the engineering side
	// const [production, setProduction] = createSignal(-1);
	const [turnsLeft, setTurnsLeft] = createSignal(-1);
	const [percent, setPercent] = createSignal(-1);

	// const truncateDecimal = (input: number) => {
	// 	return input >= 1000 ? Math.floor(input) : input;
	// };

	// Commented out until Efficiencies are sorted out on the engineering side
	// const productionBonusMap = {
	// 	[ProductionPanelCategory.BUILDINGS]: "LOC_UI_CITY_BANNER_PRODUCTION_BONUS_CONSTRUCTIBLE",
	// 	[ProductionPanelCategory.WONDERS]: "LOC_UI_CITY_BANNER_PRODUCTION_BONUS_CONSTRUCTIBLE",
	// 	[ProductionPanelCategory.UNITS]: "LOC_UI_CITY_BANNER_PRODUCTION_BONUS_UNIT",
	// 	[ProductionPanelCategory.PROJECTS]: "LOC_UI_CITY_BANNER_PRODUCTION_BONUS_PROJECT",
	// };
	// const currentProdProgress = createMemo(() => {
	// 	const cost = currentProd()?.cost ?? 0;
	// 	const progress = (currentProd()?.progress ?? 0) / 100;
	// 	return truncateDecimal(cost * progress);
	// });

	const isQueueEmpty = createMemo(() => {
		for (const item of buildQueue()) {
			if (item.type.length > 0) return false;
		}
		return true;
	});

	createEffect(() => {
		const production = props.currentProduction;
		if (!production) {
			return;
		}
		setCurrentProd(production);
		setBuildQueue(props.buildQueue);

		setTurnsLeft(props.turnsLeft);
		setPercent(props.percent);
		// setProduction(truncateDecimal(props.prodPerTurn));
	});

	return (
		<Tooltip
			initialVPosition={TooltipVerticalPosition.BOTTOM}
			initialHPosition={TooltipHorizontalPosition.RIGHT}
			offset={22}
			allowFlip={true}
		>
			{/* -------------------------------------------------------------------
					Progress Circle on Banner
				------------------------------------------------------------------- */}
			<Tooltip.Trigger>
				<div class="items-center justify-center w-6 h-6 relative">
					<RingMeter
						min={0}
						max={100}
						value={percent()}
						class="city-banner__ring city-banner__production-ring bg-cover bg-center flex size-9 self-center align-center pointer-events-auto"
					>
						<div
							class="size-4 self-center bg-contain bg-no-repeat"
							aria-label={Locale.compose(
								`{LOC_UI_CITY_BANNER_PRODUCTION} {${currentProd()?.name ?? ""}}, `,
							)}
							style={{ "background-image": currentProd()?.icon ?? "" }}
						/>
					</RingMeter>
					<Show when={turnsLeft() >= 0}>
						<div class="city-banner__turn flex flex-col relative justify-end align-center self-center w-8 mt-0-\\.5 pointer-events-none">
							<div
								class="city-banner__turn-number font-body-xs text-white text-center w-full bg-cover bg-center bg-no-repeat"
								aria-label={Locale.compose("LOC_UI_CITY_BANNER_TURNS_TO_COMPLETION", turnsLeft())}
							>
								{turnsLeft()}
							</div>
						</div>
					</Show>
				</div>
			</Tooltip.Trigger>
			{/* -------------------------------------------------------------------
					Tooltip
				------------------------------------------------------------------- */}
			<Tooltip.Content>
				<Tooltip.Frame class="w-auto min-w-62 max-w-84 self-start text-sm">
					<div
						class="size-20 relative self-center -mt-14 -mb-8 flex flex-col items-center justify-center bg-cover bg-center bg-no-repeat pointer-events-none"
						style={{ "background-image": "url(blp:base_triumph_ring)" }}
					>
						<RingMeter
							class="size-14 absolute flex justify-center bg-contain bg-center flex-auto items-center"
							min={0}
							max={100}
							value={percent()}
							animationDuration={1}
							ringImage={`url("blp:progress_ring_triumph")`}
							ringTint="rgb(143, 113, 71)"
						>
							<div
								class="size-11 self-center bg-contain bg-no-repeat"
								style={{ "background-image": currentProd()!.icon }}
							/>
						</RingMeter>
					</div>
					<div class="w-full h-7" />
					<L10n.Stylize
						class="text-secondary text-center uppercase font-title"
						text={"LOC_UI_CITY_INSPECTOR_CURRENTLY_PRODUCING"}
					/>
					<TicketSection>
						<div class="flex flex-col items-stretch justify-center">
							<ProductionTooltip
								type={currentProd()!.type}
								name={currentProd()!.name}
								category={currentProd()!.kind}
								cost={currentProd()!.cost.toString()}
								initialVPosition={TooltipVerticalPosition.BOTTOM}
								initialHPosition={TooltipHorizontalPosition.RIGHT}
								allowFlip
							>
								<TooltipKeyword>
									<L10n.Stylize
										class="font-title text-center text-sm"
										text={currentProd()!.name}
									/>
								</TooltipKeyword>
							</ProductionTooltip>
							<EntryDivider class="w-full" />
							{/* Commented out until Efficiencies are sorted out on the engineering side */}
							{/* <L10n.Stylize
								class="text-accent-3 text-xs text-center"
								args={[
									currentProdProgress(),
									truncateDecimal(currentProd()!.cost ?? 0),
									production(),
									"YIELD_PRODUCTION",
								]}
								text={"LOC_UI_CITY_BANNER_YIELD_BREAKDOWN"}
							/>
							<L10n.Stylize
								class="text-accent-3 text-xs text-center"
								args={[999, 999, currentProd()!.name]}
								text={productionBonusMap[currentProd()!.kind]}
							/>
							<EntryDivider /> */}
							<L10n.Stylize
								class="text-xs text-center"
								args={[turnsLeft()]}
								text={"LOC_UI_CITY_BANNER_TURNS_TO_COMPLETION"}
							/>
						</div>
					</TicketSection>
					<L10n.Stylize
						class="text-xs text-secondary text-center font-title uppercase mt-2"
						text={"LOC_UI_CITY_INTERACT_PRODUCTION"}
					/>
					<TicketSection class={"flex flex-row items-center justify-between min-h-9"}>
						<Show
							when={!isQueueEmpty()}
							fallback={
								<>
									<div class="grow h-px" />
									<L10n.Stylize
										class="text-sm text-accent-3 opacity-60 text-center"
										text={"LOC_UI_CITY_BANNER_EMPTY_PRODUCTION_QUEUE"}
									/>
									<div class="grow h-px" />
								</>
							}
						>
							<div class="h-px" />
							<For each={buildQueue()}>
								{(item, index) => (
									<>
										<Show when={index() > 0}>
											<div class="w-px self-stretch bg-accent-2 opacity-30 mx-2" />
										</Show>
										<div class="w-9 flex item-center justify-center">
											<Show
												when={item.type.length > 0}
												fallback={
													<div class="self-center uppercase font-title text-accent-3 opacity-60">
														{index() + 1}
													</div>
												}
											>
												<ProductionTooltip
													type={item.type}
													name={item.name}
													category={item.kind}
													cost={item.cost.toString()}
													initialVPosition={TooltipVerticalPosition.BOTTOM}
													initialHPosition={TooltipHorizontalPosition.RIGHT}
													allowFlip
												>
													<div class="flex flex-col">
														<div
															class="size-9 self-center bg-contain bg-no-repeat"
															style={{ "background-image": item.icon }}
														/>
														<div class="flex flex-row items-center justify-center">
															<div class="text-xs text-accent-3">{item.turns}</div>
															<div
																class="size-5 bg-cover bg-no-repeat"
																style={{
																	"background-image": `url("fs://game/hud_turn-timer.png")`,
																}}
															/>
														</div>
													</div>
												</ProductionTooltip>
											</Show>
										</div>
									</>
								)}
							</For>
							<div class="h-px" />
						</Show>
					</TicketSection>
				</Tooltip.Frame>
			</Tooltip.Content>
		</Tooltip>
	);
};

defineLegacyComponent(
	"city-banner-production",
	{
		attrs: {
			"data-cityid": null,
			"data-build-queue": null,
			"data-current-production": null,
			"data-prod-per-turn": "0",
			"data-turns-left": "0",
			"data-percent": "0",
		},
	},
	(attrs) => (
		<CityBannerProduction
			currentProduction={
				attrs["data-current-production"]
					? (JSON.parse(attrs["data-current-production"]) as ProductionQueueItem)
					: undefined
			}
			buildQueue={
				attrs["data-build-queue"] ? (JSON.parse(attrs["data-build-queue"]) as ProductionQueueItem[]) : []
			}
			turnsLeft={Number(attrs["data-turns-left"])}
			percent={Number(attrs["data-percent"])}
		/>
	),
);
